import { useEffect, useRef, useState } from "react";
import { clearDraft, getDraft, saveDraft } from "./activityLog";
import { createQuizBatchClient, getQuizBatchSyncMessage, mergeQuizBatch, snapshotQuizBatch } from "./quizBatchSync";
import { quiz_address } from "../contract/config";
import { WALLET_PROVIDER_CHANGED_EVENT } from "../contract/contractClients";

const LEGACY = "create_quiz_batch_v1";
const OWNER = "create_quiz_batch_owner_v1";
const read = (key, fallback) => { try { return JSON.parse(getDraft(key) || "null") ?? fallback; } catch (_) { return fallback; } };
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const persist = (key, value) => {
    const raw = JSON.stringify(value);
    saveDraft(key, raw);
    if (getDraft(key) !== raw) throw new Error("draft_local_storage_unavailable");
};

export default function useSyncedQuizBatch(cont) {
    const enabled = process.env.REACT_APP_PRIVATE_QUIZ_DRAFT_SYNC === "true";
    const [items, setItems] = useState(() => {
        const owner = read(OWNER, "");
        return owner ? read(`create_quiz_batch_sync_v1:${owner}:${quiz_address.toLowerCase()}:items`, read(LEGACY, [])) : read(LEGACY, []);
    });
    const [status, setStatus] = useState("教員ウォレットの接続を確認しています。");
    const [ready, setReady] = useState(false);
    const [locked, setLocked] = useState(false);
    const [busy, setBusy] = useState(false);
    const state = useRef({ items, client: null, key: "", base: { revision: 0, items: [] }, publishToken: "", generation: 0, pending: null });
    const update = (next) => {
        const s = state.current;
        s.items = typeof next === "function" ? next(s.items) : next;
        setItems(s.items);
        try { persist(s.key ? `${s.key}:items` : LEGACY, s.items); }
        catch (failure) { setReady(false); setStatus(getQuizBatchSyncMessage(failure)); }
    };
    const sync = () => {
        const s = state.current;
        if (s.pending) return s.pending;
        if (!s.client) return Promise.reject(new Error("draft_storage_not_configured"));
        const generation = s.generation;
        s.pending = (async () => {
            const remote = await s.client.get();
            if (generation !== state.current.generation) throw new Error("draft_account_changed");
            if (remote.revision < s.base.revision) throw new Error("draft_server_reset");
            setLocked(Boolean(remote.publishing && !s.publishToken));
            const merged = mergeQuizBatch(s.base.items, s.items, remote.items);
            update(merged);
            let saved = remote;
            if (!same(merged, remote.items)) saved = await s.client.put(remote.revision, merged, s.publishToken);
            if (generation !== state.current.generation) throw new Error("draft_account_changed");
            s.base = { revision: saved.revision, items: snapshotQuizBatch(saved.items) };
            // Drop the legacy duplicate only after the server has acknowledged these items.
            clearDraft(LEGACY);
            persist(`${s.key}:items`, s.items);
            persist(`${s.key}:base`, s.base);
            const clean = same(s.items, saved.items);
            setReady(clean);
            setStatus(remote.publishing && !s.publishToken ? getQuizBatchSyncMessage(new Error("draft_publish_locked")) : clean ? "同じ教員アカウントの出題リストと同期済み" : "出題リストを同期しています。");
            return { ...s.base, items: s.items };
        })().catch(failure => { if (generation === state.current.generation) { setReady(false); setStatus(getQuizBatchSyncMessage(failure)); } throw failure; })
            .finally(() => { s.pending = null; });
        return s.pending;
    };
    const syncRef = useRef(sync); syncRef.current = sync;

    const connect = async () => {
        const previous = state.current;
        const generation = previous.generation + 1;
        state.current = { ...previous, generation, client: null, pending: null };
        const s = state.current;
        setReady(false); setBusy(true);
        try {
            const address = String(await cont.get_connected_address?.() || "").toLowerCase();
            const previousOwner = read(OWNER, "");
            if (previousOwner && previousOwner !== address) { s.items = []; setItems([]); }
            if (!address || !await cont.isTeacher(address)) throw new Error("teacher_required");
            if (generation !== state.current.generation) return;
            const key = `create_quiz_batch_sync_v1:${address}:${quiz_address.toLowerCase()}`;
            const provider = await cont.getEthereumProviderReady();
            if (!provider) throw new Error("teacher_required");
            const client = createQuizBatchClient(provider, address);
            setStatus("出題リスト同期用の署名を確認してください。送金・トークン承認は行いません。");
            await client.authenticate();
            if (generation !== state.current.generation) return;
            const legacyOwner = read(OWNER, "");
            const local = read(`${key}:items`, null);
            s.key = key; s.client = client;
            s.base = read(`${key}:base`, { revision: 0, items: [] });
            try { s.publishToken = sessionStorage.getItem(`${key}:publish`) || ""; } catch (_) { s.publishToken = ""; }
            persist(OWNER, address);
            update(local ?? (!legacyOwner || legacyOwner === address ? s.items : []));
            await syncRef.current();
        } catch (failure) { if (generation === state.current.generation) { setStatus(getQuizBatchSyncMessage(failure)); setReady(false); } }
        finally { if (generation === state.current.generation) setBusy(false); }
    };
    const connectRef = useRef(connect); connectRef.current = connect;
    useEffect(() => {
        if (!enabled) { setReady(true); setStatus("この端末にのみ保存されています。他端末への自動同期はまだ有効になっていません。"); return; }
        let active = true;
        const start = (event) => {
            if (event?.detail?.type === "chainChanged") return;
            const next = String(event?.detail?.accounts?.[0] || "").toLowerCase();
            if (next && state.current.client && state.current.key.includes(`:${next}:`)) return;
            if (active && !state.current.authenticating) {
            state.current.authenticating = true;
            connectRef.current().finally(() => { state.current.authenticating = false; });
        } };
        const poll = () => { if (active && document.visibilityState !== "hidden" && state.current.client) syncRef.current().catch(() => {}); };
        start();
        const timer = setInterval(poll, 10000);
        window.addEventListener(WALLET_PROVIDER_CHANGED_EVENT, start);
        window.addEventListener("focus", poll);
        return () => { active = false; state.current.generation++; clearInterval(timer); window.removeEventListener(WALLET_PROVIDER_CHANGED_EVENT, start); window.removeEventListener("focus", poll); };
    }, [cont, enabled]);
    useEffect(() => {
        const timer = setTimeout(() => { if (state.current.client) syncRef.current().catch(() => {}); }, 800);
        return () => clearTimeout(timer);
    }, [items]);
    const flush = async () => {
        if (!enabled) return;
        const s = state.current;
        for (let attempt = 0; attempt < 4; attempt++) {
            await syncRef.current();
            if (s !== state.current) throw new Error("draft_account_changed");
            if (same(snapshotQuizBatch(s.items), s.base.items)) return;
        }
        throw new Error("draft_revision_conflict");
    };
    const beginPublish = async () => {
        const s = state.current;
        if (!enabled) return { items: s.items };
        await flush();
        if (!s.publishToken) s.publishToken = [...crypto.getRandomValues(new Uint8Array(32))].map(byte => byte.toString(16).padStart(2, "0")).join("");
        sessionStorage.setItem(`${s.key}:publish`, s.publishToken);
        const result = await s.client.claim(s.base.revision, s.publishToken);
        if (result.publishToken !== s.publishToken) throw new Error("draft_service_unavailable");
        // Never send a transaction unless its cross-device lock can survive a page reload.
        if (sessionStorage.getItem(`${s.key}:publish`) !== s.publishToken) throw new Error("draft_local_storage_unavailable");
        return { items: s.items };
    };
    const finishPublish = async () => {
        if (!enabled) return;
        const s = state.current;
        await flush();
        await s.client.release(s.publishToken, s.base.revision);
        s.publishToken = ""; sessionStorage.removeItem(`${s.key}:publish`);
    };
    return { enabled, items, update, status, ready, locked, busy, reconnect: () => enabled ? connectRef.current() : Promise.resolve(), sync: flush, beginPublish, finishPublish };
}
