import { keccak256, stringToHex } from "viem";
import { getLiveSignalApiBaseUrl } from "./liveSignalApi";
import { quiz_address } from "../contract/config";
import { requestWalletProvider } from "./walletRequests";

const equal = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const error = (message) => new Error(message);
export const quizDraftFingerprint = item => keccak256(stringToHex(JSON.stringify(item)));
export const snapshotQuizBatch = items => items.map(item => ({ id: item.id, fingerprint: quizDraftFingerprint(item) }));
const matchesBase = (item, base) => base?.fingerprint ? Boolean(item) && quizDraftFingerprint(item) === base.fingerprint : equal(item, base);

export function mergeQuizBatch(base, local, remote) {
    const maps = [base, local, remote].map(items => new Map(items.map(item => [item.id, item])));
    if (maps.some((map, i) => map.size !== [base, local, remote][i].length)) throw error("draft_invalid_ids");
    const merged = new Map();
    for (const id of new Set([...maps[0].keys(), ...maps[1].keys(), ...maps[2].keys()])) {
        const [before, ours, theirs] = maps.map(map => map.get(id));
        let value;
        if (matchesBase(ours, before)) value = theirs;
        else if (matchesBase(theirs, before) || equal(ours, theirs)) value = ours;
        else throw error("draft_edit_conflict");
        if (value) merged.set(id, value);
    }
    const survivors = base.filter(item => merged.has(item.id)).map(item => item.id);
    const order = items => items.map(item => item.id).filter(id => survivors.includes(id));
    const localChanged = !equal(order(local), survivors);
    const remoteChanged = !equal(order(remote), survivors);
    if (localChanged && remoteChanged && !equal(order(local), order(remote))) throw error("draft_order_conflict");
    const primary = localChanged ? local : remote;
    const ids = [...new Set([...primary.map(item => item.id), ...local.map(item => item.id), ...remote.map(item => item.id)])];
    return ids.filter(id => merged.has(id)).map(id => merged.get(id));
}

export function getQuizBatchSyncMessage(failure) {
    const messages = {
        draft_storage_not_configured: "端末間同期の永続保存先が未設定です。この端末の下書きは保持しています。",
        draft_service_unavailable: "同期サーバーに接続できません。この端末の下書きは保持しています。",
        teacher_required: "同じ教員ウォレットで接続してください。",
        authentication_required: "同期の認証期限が切れました。再接続して署名を確認してください。",
        draft_edit_conflict: "別の端末で同じ問題が編集・削除されています。どちらも上書きせず停止しました。",
        draft_order_conflict: "別の端末でも並び順が変更されています。上書きせず停止しました。",
        draft_revision_conflict: "別の端末で更新されました。再同期してから投稿してください。",
        draft_server_reset: "同期サーバーの保存状態が以前より古いため、下書きを削除せず停止しました。",
        draft_publish_locked: "別の端末で投稿中、または投稿結果の確認待ちです。元の端末で結果を確認してください。",
        draft_account_changed: "ウォレットが変わったため同期を停止しました。",
        drafts_too_large: "同期する問題・画像の合計が16MBを超えています。画像を小さくしてください。",
        draft_local_storage_unavailable: "端末の下書き保存ができないため投稿を停止しました。保存容量とブラウザーの設定を確認してください。",
    };
    return messages[failure?.message] || (Number(failure?.code) === 4001
        ? "同期用の署名がキャンセルされました。この端末の下書きは保持しています。"
        : "同期を完了できません。この端末の下書きは保持しています。");
}

export function createQuizBatchClient(provider, address, { fetcher = fetch, baseUrl = getLiveSignalApiBaseUrl() } = {}) {
    const owner = address.toLowerCase();
    let session = null;
    const request = async (path, body) => {
        const controller = new AbortController(); const timer = setTimeout(() => controller.abort(), 45000);
        try {
            const response = await fetcher(`${baseUrl}/quiz-drafts${path}`, {
                method: body === undefined ? "GET" : "POST", signal: controller.signal,
                headers: { "Content-Type": "application/json", ...(session ? { Authorization: `Bearer ${session.token}` } : {}) },
                ...(body === undefined ? {} : { body: JSON.stringify(body) }),
            });
            const result = await response.json();
            if (!response.ok) { if (response.status === 401) session = null; throw error(result.error || "draft_service_unavailable"); }
            return result;
        } catch (failure) { if (failure?.name === "AbortError") throw error("draft_service_unavailable"); throw failure; }
        finally { clearTimeout(timer); }
    };
    return {
        async authenticate() {
            if (session && session.expiresAt > Date.now()) return;
            const capability = await request("/capabilities");
            if (capability.protocol !== "private-quiz-drafts-v1" || !capability.configured
                || capability.chainId !== 80002 || capability.quizAddress !== quiz_address.toLowerCase()) throw error("draft_storage_not_configured");
            const challenge = await request("/challenge", { address: owner });
            if (typeof challenge.message !== "string" || !challenge.message.includes(`Wallet: ${owner}\n`)
                || !challenge.message.includes(`Origin: ${window.location.origin}\n`) || !challenge.message.includes(`Quiz: ${quiz_address.toLowerCase()}\n`)
                || !challenge.message.includes(`Nonce: ${challenge.id}\n`) || challenge.expiresAt <= Date.now()) throw error("draft_service_unavailable");
            const signature = await requestWalletProvider(provider, { method: "personal_sign", params: [stringToHex(challenge.message), owner] });
            const accounts = await requestWalletProvider(provider, { method: "eth_accounts" });
            if (String(accounts?.[0] || "").toLowerCase() !== owner) throw error("draft_account_changed");
            const result = await request("/session", { id: challenge.id, signature });
            if (result.address !== owner || !/^[0-9a-f]{64}$/.test(result.token) || result.expiresAt <= Date.now()) throw error("draft_service_unavailable");
            session = result;
        },
        async get() {
            const doc = await request("");
            if (!Number.isSafeInteger(doc.revision) || doc.revision < 0 || !Array.isArray(doc.items)) throw error("draft_service_unavailable");
            return doc;
        },
        put: (revision, items, publishToken) => request("", { revision, items, publishToken }),
        claim: (revision, publishToken) => request("/publish", { action: "claim", revision, publishToken }),
        release: (publishToken, revision) => request("/publish", { action: "release", publishToken, revision }),
    };
}
